import math

def knn_predict(X, y, x, k):
    dist = [math.dist(p, x) for p in X]
    nearest = sorted(range(len(X)), key=lambda i: dist[i])[:k]
    votes = {}
    for i in nearest:
        votes[y[i]] = votes.get(y[i], 0) + 1
    return max(votes, key=votes.get)

